import StatsCore
import StatsAdapters
import AppKit

// The in-app usage help lives here as plain strings: selecting a category in the
// native menu bar submenu shows that category in a native panel. No HTML file is
// bundled and no web view is ever opened. Keep this wording aligned with the
// README generated by Scripts/packaging_support.py.
struct HelpCategory {
 let id:String
 let title:String
 let items:[(String,String)]
}

enum HelpDocs {
 static func categories(for provider:StatsProvider)->[HelpCategory] {
  [
   HelpCategory(id:"tools",title:"工具与展示",items:[
    ("展示与拖动","支持「悬浮条」与「菜单栏」两种模式。悬浮条位于已识别宿主主窗口顶部，按住任意处即可拖动（位置按工具保存），轻点指标展开明细。"),
    ("闲置下沉","悬浮条约 8 秒未操作后隐去背景、只留淡化数值，融入宿主窗口；指针移入、点击或拖动时立即浮现。可在「通用」或菜单栏菜单中关闭。"),
    ("菜单栏图标","可在「通用」隐藏菜单栏图标（菜单栏模式下始终显示）；应用运行时再次打开 \(Product.name)（如在「应用程序」中双击）会直接打开设置。"),
    ("指标与明细","在「显示指标」页点击条目更换指标、上下拖动排序，并按工具勾选展开的明细行。"),
    ("Token 统计","在设置「Token 统计」页按时间窗口汇总本机活跃与已归档会话（支持合并全部工具或单看某一工具），查看输入、缓存读取与输出构成、趋势及模型/项目/会话排行。"),
   ]),
   HelpCategory(id:"tool-\(provider.rawValue)",title:"工具说明 · "+provider.name,items:[
    (provider.name+" 口径",HelpDocs.providerDetail(provider))
   ]),
   HelpCategory(id:"sessions",title:"会话与权限",items:[
    ("选择对话","支持按项目浏览或选「最近活跃会话」；Kimi Code 另支持「自动跟随当前对话」。"),
    ("辅助功能权限","菜单栏模式无需任何系统权限，开箱即用。启用悬浮条或自动跟随时，请在系统「辅助功能」中授权 /Applications/\(Product.name).app；仅读窗口位置与顶层地址，不读对话正文。"),
   ]),
   HelpCategory(id:"data",title:"数据与维护",items:[
    ("数据与未知值","仅在本机读取已有日志与数据库，不联网上传。缺失来源或无完整轮次的耗时显示 —，日志不可读时总计回退宿主计数。"),
    ("自启与联动","可在「通用」开关开机自动启动；Kimi 生命周期插件随启动自动同步，也可在「会话与权限」手动重新同步。"),
    ("检查与自动更新","可在「设置… → 关于」手动检查更新或开启「自动检查更新」「自动下载更新」；下载完成后会校验 SHA-256 与代码签名并支持一键安装重启。"),
    ("卸载","可在「设置… → 关于」点击「卸载 \(Product.name)…」，或在终端执行："+HelpDocs.uninstallCommand+"，或在开发目录运行 python3 uninstall.py --app agent（均保留宿主与会话数据）。"),
   ])
  ]
 }

 static func providerDetail(_ provider:StatsProvider)->String {
  switch provider {
  case .codex:
   return "读取本机 Codex 会话；TPS 含推理、正文与工具参数（仅统计具备本机流式起点的响应）。宿主不暴露当前对话标识，支持最近活跃或固定会话。"
  case .kimi:
   return "读取本机 Kimi Code 会话与子代理记录；TPS 含推理、正文与工具参数，上下文取宿主实测值，状态按最后记录展示。"
  }
 }

 static var uninstallCommand:String {
  "\"/Applications/\(Product.name).app/Contents/MacOS/\(Product.executable)\" --uninstall"
 }
}
